    [InlineData(true, "base=$(pwd); base=${base%/}; cd \"$base/a\"; pushd \"$base/b\" >/dev/null; declare -A OLDPWD=([0]=first [k]=kept); unset PWD; cd \"$base/c\"; printf 'set:<%s> default:<%s> count:<%s> keys:' \"${OLDPWD[0]+yes}\" \"${OLDPWD[0]-unset}\" \"${#OLDPWD[@]}\"; printf '<%s>' \"${!OLDPWD[@]}\"; printf ' values:'; printf '<%s>' \"${OLDPWD[@]}\"; printf '\\n'", "7365743A3C3E2064656661756C743A3C756E7365743E20636F756E743A3C323E206B6579733A3C303E3C6B3E2076616C7565733A3C3E3C6B6570743E0A")]
    public async Task UnassignedAggregateEntriesRemainSafeToEnumerate(bool prepared, string script, string outputHex)
    {
        // Both pinned native shells crash after the stable metadata prefix.
        // Emit an empty field safely for the null entry instead.
        var memory = new MemoryGovernor(1024 * 1024);
        using var owner = memory.CreateScope();
        await using var host = new TestHost { MemoryBudget = owner };
        foreach (var path in new[] { "/a", "/b", "/c" }) host.AddDirectory(path);
        using var cancel = new CancellationTokenSource(TimeSpan.FromSeconds(10));
        var result = prepared
            ? await new Engine().RunAsync(new Eval(Parser.Parse(script)), host, owner, cancel.Token)
            : await BashScript.RunAsync(host, script, EvaluationOptions.Default, cancel.Token);
        Assert.Equal(0, result.ExitCode);
        Assert.Equal(Convert.FromHexString(outputHex), host.StandardOutput.Content.ToArray());
        Assert.Empty(host.StandardError.Content.ToArray());
        Assert.Equal(0, host.OpenFileCount);
        owner.Dispose();
        Assert.Equal(0, memory.ReservedBytes);
    }
